// Build category-specific tabs from real package data only
foreach ($db_categories as $db_cat) {
    $slug  = $db_cat['slug'];
    $tours = !empty($tour_packages[$slug]) ? $tour_packages[$slug] : array();
    if (empty($tours)) {
        continue;
    }
    $featured_tabs[] = array(
        'key'   => $slug,
        'label' => $db_cat['name'],
        'tours' => $tours,
        'delay' => $_delay,
    );
    $_delay += 50;
}

// Prepend "All" tab when packages are available
if (!empty($_all_tours)) {
    array_unshift($featured_tabs, array(
        'key'   => 'all-tours',
        'label' => 'All',
        'tours' => $_all_tours,
        'delay' => 0,
    ));
}

