function render_counter_icon($icon)
{
    switch ($icon) {
        case 'smile': ?>
            <i class="fa-regular fa-face-grin-beam counter-icon"></i>
        <?php
            break;
        case 'plane': ?>
            <i class="fa-solid fa-plane-departure"></i>
        <?php
            break;
        case 'house': ?>
            <i class="fa-solid fa-house"></i>
        <?php
            break;
        case 'group':
        default: ?>
            <i class="fa-solid fa-user-group"></i>
    <?php
            break;
    }
}

