<?php }

function render_tour_card($tour, $base_url)
{
    if (!empty($tour['link'])) {
        $detail_url = site_url(htmlspecialchars($tour['link']));
    } elseif (!empty($tour['category_slug']) && !empty($tour['slug'])) {
        $detail_url = site_url(htmlspecialchars($tour['category_slug']) . '/' . htmlspecialchars($tour['slug']));
    } else {
        $detail_url = site_url('group-tour');
    }
?>
    <div class="product-card radius16 hover-on-image">
        <div class="image">
            <img src="<?= !empty($tour['image_src']) ? $tour['image_src'] : $base_url . 'assets/images/product/' . $tour['image'] ?>"
                width="734" height="534" loading="lazy" alt="Product Image">
            <?php if (!empty($tour['best_selling'])): ?>
                <div class="badge text text-14 fw-500 bg-warning text-white">BEST SELLING</div>
            <?php endif; ?>
        </div>
        <div class="content">
            <a href="<?= $detail_url ?>" class="no-underline product-title" aria-label="Product title">
                <h2 class="heading text-20"><?= htmlspecialchars($tour['title']) ?></h2>
            </a>
            <div class="text text-14 mt-1"><?= htmlspecialchars($tour['days']) ?></div>
            <?php if (!empty($tour['amenities'])): ?>
                <div class="d-flex gap-2 mt-2">
                    <?php foreach ($tour['amenities'] as $icon): ?>
                        <span class="fs-5"><?= $icon ?></span>
                    <?php endforeach; ?>
                </div>
            <?php endif; ?>
            <?php if (!empty($tour['highlights'])): ?>
                <div class="text text-14 fw-600 mt-2 mb-1">Tours Highlights</div>
                <div class="row g-0">
                    <?php
                    $half = (int) ceil(count($tour['highlights']) / 2);
                    $left = array_slice($tour['highlights'], 0, $half);
                    $right = array_slice($tour['highlights'], $half);
                    ?>
                    <div class="col-6">
                        <ul class="list-unstyled mb-0">
                            <?php foreach ($left as $h): ?>
                                <li class="text text-14">• <?= htmlspecialchars($h) ?></li>
                            <?php endforeach; ?>
                        </ul>
                    </div>
                    <div class="col-6">
                        <ul class="list-unstyled mb-0">
                            <?php foreach ($right as $h): ?>
                                <li class="text text-14">• <?= htmlspecialchars($h) ?></li>
                            <?php endforeach; ?>
                        </ul>
                    </div>
                </div>
            <?php endif; ?>
            <div class="price-booking-wrap mt-3">
                <div class="card-price">
                    <?php
                    $show_price = isset($tour['category_slug'])
                        && $tour['category_slug'] === 'group-tour'
                        && empty($tour['price_on_request']);
                    $pay_amount = ($show_price && !empty($tour['price'])) ? (int) preg_replace('/[^\d]/', '', (string) $tour['price']) : 0;
                    $can_pay = $pay_amount > 0 && !empty($tour['p_id']) && !empty($tour['slug']) && !empty($tour['category_slug']);

                    // Compute data attributes for the payment modal
                    $_h_num_days = 0;
                    if (!empty($tour['days'])) {
                        if (preg_match('/(\d+)\s*days?/i', $tour['days'], $_hdm))      $_h_num_days = (int) $_hdm[1];
                        elseif (preg_match('/(\d+)\s*nights?/i', $tour['days'], $_hdm)) $_h_num_days = (int) $_hdm[1] + 1;
                        else {
                            preg_match('/(\d+)/', $tour['days'], $_hdm);
                            $_h_num_days = isset($_hdm[1]) ? (int) $_hdm[1] : 0;
                        }
                    }
                    $_h_text = strtolower(($tour['title'] ?? '') . ' ' . ($tour['description'] ?? '') . ' ' . ($tour['days'] ?? ''));
                    $_h_is_bhutan = (strpos($_h_text, 'bhutan') !== false) ? 1 : 0;
                    $_h_sdf_exempt = (!$_h_is_bhutan && (strpos($_h_text, 'phuentsholing') !== false || strpos($_h_text, 'phuntsholing') !== false)) ? 1 : 0;
                    $_h_itin = !empty($tour['itinerary_json']) ? json_decode($tour['itinerary_json'], true) : array();
                    $_h_itin_slim = is_array($_h_itin) ? array_map(function ($d) {
                        return array('day' => isset($d['day']) ? $d['day'] : '', 'title' => isset($d['title']) ? $d['title'] : '', 'stay' => isset($d['stay']) ? $d['stay'] : '');
                    }, $_h_itin) : array();
                    ?>
                    <?php if ($show_price && !empty($tour['price'])): ?>
                        <span class="heading text-24">&#8377;<?= number_format($pay_amount) ?></span>
                        <div class="text text-12 text-muted">per person</div>
                    <?php else: ?>
                        <span class="heading text-18" style="color:#f97316;font-weight:700">Price On Request</span>
                    <?php endif; ?>
                </div>
                <div class="d-flex gap-2">
                    <a href="<?= $detail_url ?>" class="button button--primary button--slim" aria-label="View Details">View
                        Details</a>
                    <?php if ($can_pay): ?>
                        <button type="button" class="button button--primary button--slim tp-pay-btn js-package-pay"
                            data-bs-toggle="modal" data-bs-target="#packagePaymentModal"
                            data-package-id="<?= (int) $tour['p_id'] ?>"
                            data-package-title="<?= htmlspecialchars($tour['title'], ENT_QUOTES, 'UTF-8') ?>"
                            data-package-slug="<?= htmlspecialchars($tour['slug'], ENT_QUOTES, 'UTF-8') ?>"
                            data-package-category-slug="<?= htmlspecialchars($tour['category_slug'], ENT_QUOTES, 'UTF-8') ?>"
                            data-amount-display="<?= htmlspecialchars('Rs ' . number_format($pay_amount), ENT_QUOTES, 'UTF-8') ?>"
                            data-package-rate="<?= (int) $pay_amount ?>" data-is-bhutan="<?= $_h_is_bhutan ?>"
                            data-sdf-exempt="<?= $_h_sdf_exempt ?>" data-num-days="<?= $_h_num_days ?>"
                            data-itinerary="<?= htmlspecialchars(json_encode($_h_itin_slim, JSON_UNESCAPED_UNICODE), ENT_QUOTES, 'UTF-8') ?>"
                            aria-label="Pay now">Book Now</button>
                    <?php endif; ?>
                    <a href="https://wa.me/<?= isset($wa_number) ? $wa_number : '' ?>?text=<?= urlencode('Hello TripJyada! I am interested in ' . $tour['title'] . '. Please share details.') ?>"
                        target="_blank" class="btn btn-success d-flex align-items-center justify-content-center rounded p-2"
                        aria-label="WhatsApp">
                        <i class="fa-brands fa-whatsapp" aria-hidden="true"></i>
                    </a>
                </div>
            </div>
        </div>
    </div>
<?php } ?>

