function render_featured_card($tour, $base_url)
{
    if (!empty($tour['link'])) {
        $detail_url = site_url(htmlspecialchars($tour['link']));
    } elseif (!empty($tour['category_slug']) && !empty($tour['slug'])) {
        $detail_url = site_url(htmlspecialchars($tour['category_slug']) . '/' . htmlspecialchars($tour['slug']));
    } else {
        $detail_url = site_url('group-tour');
    }
    $img      = !empty($tour['image_src']) ? $tour['image_src'] : $base_url . 'assets/images/product/' . $tour['image'];
    $wa_num   = '919558515518';
    $phone    = 'tel:+919558515518';
    $wa_msg   = urlencode('Hello TripJyada! I am interested in ' . $tour['title'] . '. Please share details.');
